import{_ as t,o as a,c as n,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Calculated Fields","description":"Use linked value, calculate sum, and formula — derived values in ApptiveGrid.","frontmatter":{"title":"Calculated Fields","description":"Use linked value, calculate sum, and formula — derived values in ApptiveGrid."},"headers":[],"relativePath":"en/grids/berechnete-felder.md","filePath":"en/grids/berechnete-felder.md","lastUpdated":1787319236000}'),s={name:"en/grids/berechnete-felder.md"};function r(o,e,l,d,c,h){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h1 id="calculated-fields" tabindex="-1">Calculated Fields <a class="header-anchor" href="#calculated-fields" aria-label="Permalink to &quot;Calculated Fields&quot;">​</a></h1><p>Three column types calculate their value themselves instead of having it entered by hand:</p><table tabindex="0"><thead><tr><th>Type</th><th>From what</th></tr></thead><tbody><tr><td><strong>Use linked value</strong></td><td>a linked entry</td></tr><tr><td><strong>Calculate sum</strong></td><td>multiple linked entries</td></tr><tr><td><strong>Formula</strong></td><td>an expression</td></tr></tbody></table><p>All three are <strong>read-only</strong> and are <strong>not available in forms</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Two require a link</p><p><em>Use linked value</em> and <em>Calculate sum</em> only work if the Grid already has a link. Create that first — see <a href="/en/grids/verknuepfungen">Linking Grids</a>.</p></div><hr><h2 id="use-linked-value" tabindex="-1">Use linked value <a class="header-anchor" href="#use-linked-value" aria-label="Permalink to &quot;Use linked value&quot;">​</a></h2><p>Pulls a value from a linked entry into the current Grid.</p><p><strong>Example:</strong> The Grid &quot;Registrations&quot; references &quot;Events&quot; via <em>Link record</em>. With <em>Use linked value</em> you pull the event date directly into the registration.</p><p><strong>Settings:</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Link field</strong></td><td>Which link column is used</td></tr><tr><td><strong>Target field</strong></td><td>Which field is pulled from the linked entry</td></tr></tbody></table><p>The value updates automatically. If the date in &quot;Events&quot; changes, it changes in every registration along with it.</p><div class="tip custom-block"><p class="custom-block-title">Use linked value instead of copying</p><p>The most common beginner mistake is writing recurring values into both Grids. Sooner or later, the data drifts apart. <em>Use linked value</em> keeps it in sync automatically — the information continues to exist in only one place.</p></div><div class="tip custom-block"><p class="custom-block-title">Linked-in values are filterable</p><p>A pulled-in date can be filtered and sorted like a normal field. This lets you build a view &quot;Registrations for upcoming events&quot; without maintaining the date twice.</p></div><hr><h2 id="calculate-sum" tabindex="-1">Calculate sum <a class="header-anchor" href="#calculate-sum" aria-label="Permalink to &quot;Calculate sum&quot;">​</a></h2><p>Sums a numeric field across all linked entries.</p><p><strong>Example:</strong> The Grid &quot;Invoices&quot; references &quot;Line items&quot; via <em>Link multiple records</em>. With <em>Calculate sum</em>, the total amount appears automatically on the invoice.</p><p><strong>Settings:</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Link field</strong></td><td>A column of type <em>Link multiple records</em></td></tr><tr><td><strong>Target field</strong></td><td>The numeric field to sum</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Requires the multi-link type</p><p>This type doesn&#39;t work with <em>Link record</em> — there&#39;s nothing to sum. You need <strong>Link multiple records</strong>.</p></div><p>Typical applications: invoice totals, project effort, order values, participant counts.</p><hr><h2 id="formula" tabindex="-1">Formula <a class="header-anchor" href="#formula" aria-label="Permalink to &quot;Formula&quot;">​</a></h2><p>Calculates a value from an expression.</p><p><strong>Settings:</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Expression</strong></td><td>The calculation, in ApptiveScript</td></tr><tr><td><strong>Result type</strong></td><td>What type the result has</td></tr></tbody></table><p>The editor (<em>Edit an expression</em>) shows a <strong>sample result</strong> and the determined <strong>type</strong>. Rely on the type: the sample result stays empty for some functions even though the column does calculate at runtime — <a href="/en/apptivescript/editor#sample-result-and-type">why is explained in the expression editor</a>.</p><div class="warning custom-block"><p class="custom-block-title">The result must be a displayable value</p><p>A formula column always has to end on a value a column can display — text, number, date, boolean. An expression that produces a compound result can&#39;t be displayed.</p><p>Two cases where this happens — both can be fixed by appending an access:</p><table tabindex="0"><thead><tr><th>The expression ends on …</th><th>Append</th></tr></thead><tbody><tr><td><code>parseJSON()</code> — a collection of keys and values</td><td><code>.get(&#39;&lt;key&gt;&#39;)</code></td></tr><tr><td><code>match()</code> — a list of all matches</td><td><code>.at(1)</code> for the first match</td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fieldValue(&#39;answer&#39;).parseJSON().get(&#39;a&#39;)</span></span>
<span class="line"><span>fieldValue(&#39;code&#39;).match(&#39;[a-z]&#39;).at(1)</span></span></code></pre></div></div><p>How an expression is structured is covered under <a href="/en/apptivescript/schreibweise">Syntax</a>; how to reference other fields, under <a href="/en/apptivescript/werte-referenzieren">Referencing values</a>. The complete list of functions is in the <a href="/en/referenz/apptivescript-funktionen">function reference</a>.</p><div class="tip custom-block"><p class="custom-block-title">Build it up step by step</p><p>Start with a single field and append one function at a time. The editor shows the determined type after every step — and with it, which functions are possible next.</p></div><hr><h2 id="the-most-important-limitation" tabindex="-1">The most important limitation <a class="header-anchor" href="#the-most-important-limitation" aria-label="Permalink to &quot;The most important limitation&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Calculated fields don&#39;t trigger flows</p><p>Fields of type <strong>Use linked value</strong>, <strong>Calculate sum</strong>, and <strong>Formula</strong> can <strong>not</strong> be chosen as the triggering field in the flow trigger <em>Entry was changed</em>. They don&#39;t even show up there.</p><p>So if a calculated sum changes, no flow starts.</p></div><p><strong>The workaround:</strong> React to the field that caused the calculation.</p><p>Instead of &quot;when the invoice total changes,&quot; build the flow on &quot;when a line item is added&quot; — that is, a <em>New entry</em> trigger on the &quot;Line items&quot; Grid.</p><p>The same applies to <strong>Created at</strong>: this field is also unavailable as a condition.</p><h2 id="which-type-for-which-task" tabindex="-1">Which type for which task <a class="header-anchor" href="#which-type-for-which-task" aria-label="Permalink to &quot;Which type for which task&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to …</th><th>Type</th></tr></thead><tbody><tr><td>Show a value from a linked entry</td><td><strong>Use linked value</strong></td></tr><tr><td>Sum amounts across multiple linked entries</td><td><strong>Calculate sum</strong></td></tr><tr><td>Compute values within a single entry</td><td><strong>Formula</strong></td></tr><tr><td>React to a change</td><td><strong>Flow</strong> — calculated fields don&#39;t trigger</td></tr><tr><td>Build metrics across an entire view</td><td><a href="/en/ansichten/filtern-sortieren-gruppieren">Grouping with aggregate</a></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Calculation beats automation</p><p>For derived values, a calculated field is almost always better than a flow: it updates instantly, doesn&#39;t use up a flow run from your plan, and can&#39;t fail.</p><p>A flow is worth it when something should <strong>happen</strong> — not when something should merely be <strong>displayed</strong>.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/grids/verknuepfungen">Linking Grids</a></li><li><a href="/en/referenz/spaltentypen">Column type reference</a></li><li><a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></li></ul>`,42)])])}const m=t(s,[["render",r]]);export{p as __pageData,m as default};
